tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-24T00:10:43.787Z', '2026-10-24T00:10:43.787Z', 'Abandoned cart reminder', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
